arguments.command:
$rev="E:\项目_手动重构\build\final-hone-dh1b_5mf\project\workspace\cooperation\8e577bfc8472\reviews\7aa1b917-3373-4cbe-b708-bf0eaf8dfd50\source"
$main="E:\项目_手动重构\build\final-hone-dh1b_5mf\project\workspace\cooperation\8e577bfc8472\main"
Write-Host "--- candidate source top ---"
Get-ChildItem -Force $rev | Select-Object Name
Write-Host "--- manifest ---"
Get-Content "E:\项目_手动重构\build\final-hone-dh1b_5mf\project\workspace\cooperation\8e577bfc8472\reviews\7aa1b917-3373-4cbe-b708-bf0eaf8dfd50\manifest.json" -Raw | Select-Object -First 1
Write-Host "--- hash compare vs main HEAD 59d8175 ---"
$revFiles = Get-ChildItem -Recurse -File $rev | Where-Object { $_.FullName -notmatch '\\__pycache__\\|\.pyc$' } | ForEach-Object { $_.FullName.Substring($rev.Length+1) }
$diffCount=0
foreach($rel in $revFiles){
  $a=Join-Path $rev $rel; $b=Join-Path $main $rel
  if(-not (Test-Path -LiteralPath $b)){ Write-Host "ONLY-IN-CANDIDATE $rel"; $diffCount++ }
  elseif((Get-FileHash -LiteralPath $a).Hash -ne (Get-FileHash -LiteralPath $b).Hash){ Write-Host "DIFF $rel"; $diffCount++ }
}
Write-Host "candidate files: $($revFiles.Count), differences: $diffCount"
